&lt;li data-charcodes=&quot;8226&quot; data-font=&quot;Arial,Sans-Serif&quot; data-buautonum=&quot;8&quot; data-margin=&quot;270&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-scheme-color=&quot;@000000,1,&quot; data-usefontface=&quot;true&quot; data-contrast=&quot;none&quot;&gt;Support preventative maintenance schedules, performing regular inspections, cleaning, and &lt;/span&gt;&lt;span data-scheme-color=&quot;@000000,1,&quot; data-usefontface=&quot;true&quot; data-contrast=&quot;none&quot;&gt;necessary repairs on all data center equipment to prevent unplanned downtime.&lt;/span&gt;​&lt;/li&gt;
&lt;/ul&gt;
