&lt;li data-charcodes=&quot;8226&quot; data-font=&quot;Arial,Sans-Serif&quot; data-buautonum=&quot;8&quot; data-margin=&quot;270&quot; data-aria-posinset=&quot;11&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-scheme-color=&quot;@000000,,&quot; data-usefontface=&quot;true&quot; data-contrast=&quot;none&quot;&gt;Must have reliable transportation to and from the designated work site.&lt;/span&gt;&lt;/li&gt;
