&lt;li class=&quot;ace-line ace-line old-record-id-WdnRdmRH3oM0D9x6cKkuhD3YsAe&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;Excel in quantitative research with various mathematics tools.&lt;br&gt;&lt;br&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Perks &amp;amp; Benefits&amp;nbsp;&lt;/strong&gt;&lt;/h2&gt;
&lt;ul class=&quot;list-bullet1&quot;&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-Gb04dtjtMoHmldxfAjXuI6P4snC&quot; data-list=&quot;bullet&quot;&gt;
